\copy (SELECT CASE WHEN discount = 0 THEN '0% (No Discount)' WHEN discount <= 0.2 THEN 'Low (up to 20%)' ELSE 'High (> 20%)' END AS discount_tier, COUNT(*) AS total_transactions, SUM(sales) AS total_sales, SUM(profit) AS total_profit, ROUND(SUM(profit) / NULLIF(SUM(sales), 0) * 100, 2) AS profit_margin_pct FROM main GROUP BY 1 ORDER BY total_profit DESC) TO 'sql/results/discount_tiers_impact.csv' CSV HEADER
\copy (SELECT category, sub_category, SUM(sales) AS total_sales, SUM(profit) AS total_profit, ROUND(SUM(profit) / NULLIF(SUM(sales), 0) * 100, 2) AS profit_margin_pct FROM main GROUP BY category, sub_category ORDER BY total_profit ASC) TO 'sql/results/sub_category_breakdown.csv' CSV HEADER
\copy (WITH y AS (SELECT EXTRACT(YEAR FROM order_date) AS year, SUM(sales) AS total_sales, SUM(profit) AS total_profit, ROUND(SUM(profit) / NULLIF(SUM(sales), 0) * 100, 2) AS profit_margin_pct FROM main GROUP BY 1) SELECT year, total_sales, LAG(total_sales) OVER (ORDER BY year) AS previous_year_sales, ROUND((total_sales - LAG(total_sales) OVER (ORDER BY year)) / NULLIF(LAG(total_sales) OVER (ORDER BY year), 0) * 100, 2) AS yoy_sales_growth_pct, total_profit, profit_margin_pct FROM y ORDER BY year) TO 'sql/results/yoy_performance.csv' CSV HEADER